#include "../GsmAtlasJob.h"
#include <cstdio>
namespace GSM {volatile LONG generation=0;}
static unsigned checks=0;static void Check(bool b,const char*s){++checks;if(!b){std::fprintf(stderr,"FAIL %s\n",s);throw 1;}}
static void Bad(const std::string&s){bool bad=false;try{GsmAtlas::Canonical(s);}catch(...){bad=true;}Check(bad,"invalid source path rejected");}
static void Changed(void*){InterlockedIncrement(&GSM::generation);}
static std::vector<std::wstring>files,dirs;
static void Mkdir(const std::string&s){std::wstring w=GsmAtlas::Wide(s);for(size_t i=3;i<=w.size();++i)if(i==w.size()||w[i]=='\\'){std::wstring part=w.substr(0,i);if(GetFileAttributesW(part.c_str())==INVALID_FILE_ATTRIBUTES){Check(CreateDirectoryW(part.c_str(),NULL)!=FALSE,"fixture directory");dirs.push_back(part);}}}
static void Write(const std::string&s,const char*data){size_t at=s.find_last_of('/');Mkdir(s.substr(0,at));std::wstring w=GsmAtlas::Wide(s);HANDLE f=CreateFileW(w.c_str(),GENERIC_WRITE,0,NULL,CREATE_ALWAYS,0,NULL);Check(f!=INVALID_HANDLE_VALUE,"candidate file create");DWORD n=0;Check(WriteFile(f,data,static_cast<DWORD>(std::strlen(data)),&n,NULL)&&n==std::strlen(data)&&CloseHandle(f),"candidate file write");files.push_back(w);}
static void Cleanup(){for(size_t i=files.size();i>0;--i)DeleteFileW(files[i-1].c_str());for(size_t i=dirs.size();i>0;--i)RemoveDirectoryW(dirs[i-1].c_str());}
int main(int argc,char**argv){if(argc!=2)return 2;try{
    std::string path=argv[1];HANDLE f=CreateFileW(GsmAtlas::Wide(path).c_str(),GENERIC_WRITE,0,NULL,CREATE_ALWAYS,0,NULL);Check(f!=INVALID_HANDLE_VALUE,"fixture create");std::vector<unsigned char>data(262144,0x5a);DWORD done=0;Check(WriteFile(f,&data[0],static_cast<DWORD>(data.size()),&done,NULL)&&done==data.size()&&CloseHandle(f),"fixture write");unsigned char digest[32];Check(AtlasView::Digest(&data[0],static_cast<DWORD>(data.size()),digest),"fixture digest");std::string sha;const char*hex="0123456789abcdef";for(unsigned i=0;i<32;++i){sha+=hex[digest[i]>>4];sha+=hex[digest[i]&15];}
    GsmAtlas::Job job;AtlasView::U64 budget=8ULL*1024*1024*1024;Check(GsmAtlas::HashFile(path,sha,job,budget),"actual bounded hash");Check(job.read.readBytes==262144,"source byte counter");budget=65536;Check(!GsmAtlas::HashFile(path,sha,job,budget),"declared size cap");budget=8ULL*1024*1024*1024;std::string wrong=sha;wrong[0]=wrong[0]=='a'?'b':'a';Check(!GsmAtlas::HashFile(path,wrong,job,budget),"source SHA mismatch");
    job.read.readBytes=0;job.read.afterChunk=Changed;budget=8ULL*1024*1024*1024;Check(!GsmAtlas::HashFile(path,sha,job,budget)&&job.read.readBytes==65536&&job.read.cancel,"load generation cancels at64KiB without MapScreen Tick");InterlockedExchange(&GSM::generation,0);InterlockedExchange(&job.read.cancel,0);job.read.afterChunk=NULL;
    Bad("relative.mod");Bad("//server/share/file.mod");Bad(path+std::string(1,'\0')+"suffix");Bad(path+"\n");Bad(path+":ads");
    boost::property_tree::ptree t;Check(GsmAtlas::Json("{\"path\":\"D:/missing\\u0000suffix\"}",t),"escaped NUL JSON decodes");Bad(t.get<std::string>("path"));
    // Actual filesystem resolver equivalence to the producer, read-only.
    job.game="D:/SteamLibrary/steamapps/common/Kenshi/";job.engine=job.game+"RE_Kenshi/Kenshi_x64.exe";DWORD start=GetTickCount();std::set<std::wstring>sources=GsmAtlas::CurrentSources(job);Check(sources.size()>=5&&sources.size()<=512,"actual enabled candidate set bounded");std::printf("Current native-source candidates=%u enumerationMs=%lu\n",unsigned(sources.size()),GetTickCount()-start);
    std::ostringstream fixture;fixture<<path.substr(0,path.find_last_of('/'))<<"/source-fixture-"<<GetCurrentProcessId();std::string root=fixture.str();GsmAtlas::Job fake;fake.game=root+"/steamapps/common/Kenshi/";fake.engine=fake.game+"RE_Kenshi/Kenshi_x64.exe";
    Write(fake.game+"data/mods.cfg","Foo.mod\n");Write(fake.game+"data/gamedata.base","base");Write(fake.game+"data/Dialogue.mod","dialogue");Write(fake.game+"data/newland/land/fullmap.tif","height");Write(fake.engine,"engine");Mkdir(fake.game+"mods");Write(root+"/steamapps/workshop/content/233860/123/Foo.mod","workshop");
    std::set<std::wstring>before=GsmAtlas::CurrentSources(fake);Check(before.size()==6,"fixture includes5mandatory+Workshop candidate");Write(fake.game+"mods/Foo/Foo.mod","new local shadow");std::set<std::wstring>after=GsmAtlas::CurrentSources(fake);Check(after.size()==7&&before!=after,"new local shadow changes actual current source set");Check(std::includes(after.begin(),after.end(),before.begin(),before.end()),"all candidates retained instead of guessed priority");
    Check(DeleteFileW(GsmAtlas::Wide(root+"/steamapps/workshop/content/233860/123/Foo.mod").c_str())!=FALSE,"remove Workshop fixture");Check(GsmAtlas::CurrentSources(fake).size()==6,"removed Workshop candidate changes set");Write(fake.game+"data/mods.cfg","");Check(GsmAtlas::CurrentSources(fake).size()==5,"disabled mod excludes both candidates");Write(fake.game+"data/mods.cfg","Foo.mod\nMissing.mod\n");bool unresolved=false;try{GsmAtlas::CurrentSources(fake);}catch(...){unresolved=true;}Check(unresolved,"new unresolved enabled source refused");
    Cleanup();DeleteFileW(GsmAtlas::Wide(path).c_str());std::printf("GST2 worker PASS %u checks\n",checks);return 0;
}catch(...){Cleanup();DeleteFileW(GsmAtlas::Wide(argv[1]).c_str());return 1;}}
